import json, os, pathlib, shutil, socket, subprocess, tempfile, time
root = pathlib.Path(tempfile.mkdtemp(prefix='shards-repro-', dir='/testbed'))
server = '/testbed/src/valkey-server'
cli = '/testbed/src/valkey-cli'
ports = list(range(17600, 17606))
processes = {}
def args(i):
    d = root / str(i)
    d.mkdir(exist_ok=True)
    return [server, '--port', str(ports[i]), '--bind', '127.0.0.1', '--protected-mode', 'no', '--cluster-enabled', 'yes', '--cluster-config-file', str(d / 'nodes.conf'), '--cluster-node-timeout', '1000', '--cluster-ping-interval', '100', '--dir', str(d), '--save', '', '--appendonly', 'no', '--loglevel', 'warning']
def raw(i, *cmd, timeout=10):
    p = subprocess.run([cli, '-p', str(ports[i]), '--raw', *map(str, cmd)], text=True, capture_output=True, timeout=timeout)
    if p.returncode: raise RuntimeError(p.stderr)
    return p.stdout.strip()
def shards(i):
    p = subprocess.run([cli, '-p', str(ports[i]), '--json', 'cluster', 'shards'], text=True, capture_output=True, timeout=10)
    if p.returncode: raise RuntimeError(p.stderr)
    return json.loads(p.stdout)
def wait(check, label, seconds=30):
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline:
        try:
            if check(): return
        except (RuntimeError, ValueError): pass
        time.sleep(.1)
    raise RuntimeError('Timed out: ' + label)
def shard_for(reply, nid):
    for shard in reply:
        shard = dict(zip(shard[::2], shard[1::2])) if isinstance(shard, list) else shard
        ns = [dict(zip(n[::2], n[1::2])) if isinstance(n, list) else n for n in shard['nodes']]
        if any(n['id'] == nid for n in ns): return {'slots': shard['slots'], 'nodes': ns}
try:
    for port in ports + [p+10000 for p in ports]:
        with socket.socket() as s: s.bind(('127.0.0.1', port))
    for i in range(6): processes[i] = subprocess.Popen(args(i), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for i in range(6): wait(lambda i=i: raw(i, 'ping') == 'PONG', 'node startup')
    for i in range(1,6): raw(0, 'cluster', 'meet', '127.0.0.1', ports[i])
    wait(lambda: all('cluster_known_nodes:6' in raw(i,'cluster','info') for i in range(6)), 'cluster mesh')
    ids = [raw(i,'cluster','myid') for i in range(6)]
    for i, slots in enumerate([(0,5460), (5461,10922), (10923,16383)]): raw(i,'cluster','addslotsrange',*slots)
    wait(lambda: all('cluster_slots_assigned:16384' in raw(i,'cluster','info') for i in range(6)), 'slot propagation')
    for i in range(3): raw(i+3,'cluster','replicate',ids[i])
    wait(lambda: all('master_link_status:up' in raw(i,'info','replication') for i in range(3,6)), 'replica sync')
    wait(lambda: all('cluster_state:ok' in raw(i,'cluster','info') for i in range(6)), 'cluster healthy')
    print('Before failover:', json.dumps(shard_for(shards(1), ids[0])))
    processes[0].kill(); processes[0].wait()
    wait(lambda: raw(3,'role').splitlines()[0] == 'master', 'automatic failover')
    wait(lambda: all('cluster_state:ok' in raw(i,'cluster','info') for i in range(1,6)), 'cluster recovery')
    failed = []
    for i in range(1,6):
        shard = shard_for(shards(i), ids[0])
        print('After failover, observer', i, ':', json.dumps(shard))
        if shard['slots'] == []: failed.append(i)
    assert failed, 'Did not reproduce empty slots'
    print('REPRODUCED: slot owner promoted, but CLUSTER SHARDS slots are empty on observers', failed)
    for i in failed:
        raw(i,'shutdown','nosave'); processes[i].wait(timeout=10)
        cmd = ['peeky','probe','.','--binary','src/valkey-server','--at','src/cluster_legacy.c:5675','--capture','n.name,n.flags,n.numslots,n.slot_info_pairs_count,n.slot_info_pairs','--hits','3','--until','exit','--timeout','120','--',*args(i)[1:]]
        print('PEEKY COMMAND:', ' '.join(cmd))
        probe = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        try:
            wait(lambda: raw(i,'ping') == 'PONG', 'Peeky server startup', seconds=90)
            observed = shard_for(shards(i),ids[0])
            print('Peeky server SHARDS:',json.dumps(observed))
            raw(i,'shutdown','nosave')
            output = probe.communicate(timeout=120)[0]
            print(output)
            if observed['slots'] == []: break
        finally:
            if probe.poll() is None:
                probe.terminate(); probe.wait(timeout=10)
finally:
    for p in processes.values():
        if p.poll() is None: p.terminate()
    for p in processes.values():
        try: p.wait(timeout=10)
        except subprocess.TimeoutExpired: p.kill(); p.wait()
    shutil.rmtree(root)
