end = old.index('\n/* Add to the output buffer of the given client, an array of slot (start, end)', start)
replacement = '''/* Add the shard reply of a single shard based on its list of nodes. */
void addShardReplyForClusterShards(client *c, list *nodes) {
    serverAssert(listLength(nodes) > 0);
    addReplyMapLen(c, 2);
    addReplyBulkCString(c, "slots");

    /* A failed primary may still be in the shard after failover. Find the
     * node that actually owns slots rather than relying on role or list order. */
    clusterNode *slot_owner = NULL;
    listIter li;
    listRewind(nodes, &li);
    for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
        clusterNode *n = listNodeValue(ln);
        if (n->slot_info_pairs != NULL) {
            slot_owner = n;
            break;
        }
    }

    if (slot_owner != NULL) {
        serverAssert((slot_owner->slot_info_pairs_count % 2) == 0);
        addReplyArrayLen(c, slot_owner->slot_info_pairs_count);
        for (int i = 0; i < slot_owner->slot_info_pairs_count; i++)
            addReplyLongLong(c, (unsigned long)slot_owner->slot_info_pairs[i]);
    } else {
        /* If no slot info pair is provided, the shard owns no slots. */
        addReplyArrayLen(c, 0);
    }

    addReplyBulkCString(c, "nodes");
    addReplyArrayLen(c, listLength(nodes));
    listRewind(nodes, &li);
    for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
        clusterNode *n = listNodeValue(ln);
        addNodeDetailsToShardReply(c, n);
        clusterFreeNodesSlotsInfo(n);
    }
}
'''
new = old[:start] + replacement + old[end:]
